import { useParams } from 'react-router-dom'
import { useQuery } from '@tanstack/react-query'
import { projectsService } from '@/integrations/supabase/projects'
import { objectivesService } from '@/integrations/supabase/objectives'

export function ProjectDashboardPage() {
  const { projectId } = useParams()
  const { data: project } = useQuery({
    queryKey: ['project', projectId],
    queryFn: () => projectsService.getProject(projectId ?? ''),
    enabled: !!projectId,
  })
  const { data: objectives = [] } = useQuery({
    queryKey: ['objectives', projectId],
    queryFn: () => objectivesService.listObjectives(projectId ?? ''),
    enabled: !!projectId,
  })

  const stats = [
    { label: 'Total objectives', value: objectives.length },
    { label: 'In progress', value: objectives.filter((o) => o.status === 'in_progress').length },
    { label: 'Completed', value: objectives.filter((o) => o.status === 'completed').length },
    { label: 'Fund balance', value: `$${(project?.fundBalance ?? 0).toLocaleString()}` },
  ]

  return (
    <div className="h-full overflow-y-auto p-6">
      <div className="max-w-4xl mx-auto">
        <h2 className="font-semibold mb-6">Dashboard</h2>
        <div className="grid grid-cols-2 md:grid-cols-4 gap-4 mb-8">
          {stats.map((s) => (
            <div key={s.label} className="bg-surface rounded-xl border border-border p-4">
              <p className="text-xs text-muted-foreground">{s.label}</p>
              <p className="text-2xl font-bold mt-1">{s.value}</p>
            </div>
          ))}
        </div>
        <div className="bg-surface rounded-xl border border-border p-6 text-center text-muted-foreground">
          <p className="text-sm">Charts and analytics will appear here</p>
        </div>
      </div>
    </div>
  )
}
